// Keywords that usually work well with pixel sorting
keywords = ['winter', 'waterfall', 'iceberg', 'car', 'desert', 'mountain'];

let url = "https://source.unsplash.com/";

let direction = "vertical";
let threshold = 50;
let pixelDistance = 1;

let editable = true;
let editRadius = 30;

let img;
let changes;

function preload() {
	img = loadImage(url + str(windowWidth) + 'x' + str(windowHeight) + '/?' + random(keywords));
}

function setup() {
	createCanvas(img.width, img.height);
	generatePixelSort();
	//// noLoop() removed for animation
}

function draw() {
	image(img, 0, 0);
	if(editable) {
		push();
		stroke(0, 255, 0);
		noFill();
		circle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), editRadius * 2);
		pop();
	}
}

function generatePixelSort() {
	changes = detectPixelChanges(img, threshold, pixelDistance, direction, false);
	for (let i = 0; i < changes.length; i++) {
		if (i < changes.length - 1) {
			pixelSortTo(
				img,
				changes[i].x,
				changes[i].y,
				changes[i + 1].x,
				changes[i + 1].y,
				direction
			);
		} else {
			pixelSort(img, changes[i].x, changes[i].y, direction);
		}
	}
	img.updatePixels();
}

function detectPixelChanges(
	img,
	threshold,
	distance = 1,
	direction = "vertical",
	onlyFirst = true
) {
	let results = [];
	direction =
		direction == "horizontal" ? createVector(1, 0) : createVector(0, 1);
	let pos = createVector();

	for (let j = 0, lim = direction.x ? img.height : img.width; j < lim; j++) {
		for (let i = 0, lim = direction.x ? img.width : img.height; i < lim; i++) {
			let colBefore = getPixelValue(
				img,
				direction.x ? i - distance : j,
				direction.x ? j : i - distance
			);
			if (colBefore) {
				let col = getPixelValue(img, direction.x ? i : j, direction.x ? j : i);
				let d = dist(
					colBefore[0],
					colBefore[1],
					colBefore[2],
					col[0],
					col[1],
					col[2]
				);
				if (d > threshold) {
					//point(direction.x ? i : j, direction.x ? j : i);
					results.push(createVector(direction.x ? i : j, direction.x ? j : i));
					if (onlyFirst) break;
				}
			}
		}
	}
	return results;
}

function getPixelValue(img, x, y) {
	if (x < 0 || x > img.width - 1 || y < 0 || y > img.height - 1) return null;
	if (!img.pixels.length) img.loadPixels();
	let i = 4 * (x + y * img.width);
	let r = img.pixels[i];
	let g = img.pixels[i + 1];
	let b = img.pixels[i + 2];
	let a = img.pixels[i + 3];
	return [r, g, b, a];
}

function setPixelValue(img, x, y, colR, colG, colB, colA = 255) {
	if (x < 0 || x > img.width - 1 || y < 0 || y > img.height - 1) return null;
	if (!img.pixels.length) img.loadPixels();
	let i = 4 * (x + y * img.width);
	img.pixels[i] = colR;
	img.pixels[i + 1] = colG;
	img.pixels[i + 2] = colB;
	img.pixels[i + 3] = colA;
}

function pixelSort(img, x, y, direction = "vertical") {
	direction =
		direction == "horizontal" ? createVector(1, 0) : createVector(0, 1);
	let pix = [];
	let start = direction.x ? x : y;
	let end = direction.x ? img.width : img.height;
	for (let i = start; i < end; i++) {
		let val = getPixelValue(img, direction.x ? i : x, direction.x ? y : i);
		pix.push(val);
	}

	pix.sort(sortFunction);
	let i = 0;
	for (let p of pix) {
		setPixelValue(
			img,
			x + direction.x * i,
			y + direction.y * i,
			p[0],
			p[1],
			p[2]
		);
		i++;
	}
}

function pixelSortTo(img, x1, y1, x2, y2, direction = "vertical") {
	direction =
		direction == "horizontal" ? createVector(1, 0) : createVector(0, 1);
	let pix = [];
	let start = direction.x ? x1 : y1;
	let end = direction.x ? img.width : img.height;
	for (let i = start; i < end; i++) {
		let x = direction.x ? i : x1;
		let y = direction.x ? y1 : i;
		if (x == x2 && y == y2) break;
		let val = getPixelValue(img, x, y);
		pix.push(val);
	}

	pix.sort(sortFunction);
	let i = 0;
	for (let p of pix) {
		setPixelValue(
			img,
			x1 + direction.x * i,
			y1 + direction.y * i,
			p[0],
			p[1],
			p[2]
		);
		i++;
	}
}

function sortFunction(a, b) {
	//return brightness(window.color(color(b[0], b[1], b[2]))) - brightness(window.color(color(a[0], a[1], a[2])));
	//return b[0] * b[1] * b[2] - a[0] * a[1] * a[2];
	return -(b[0] - a[0] + b[1] - a[1] + b[2] - a[2]);
}

function mouseWheel(event) {
	editRadius += event.delta / 10;
	editRadius = constrain(editRadius, 5, 200);
}

function mouseClicked() {
	remove
